// Modal.js

import React, { useState, useEffect } from 'react';
import { DayPicker } from 'react-day-picker';
import 'react-day-picker/dist/style.css';

// Import the en-GB locale from date-fns to start the week on Monday
import enGB from 'date-fns/locale/en-GB';

// Import Capacitor's Local Notifications
import { LocalNotifications } from '@capacitor/local-notifications';

const Modal = ({
  title,
  onClose,
  task,
  occurrenceDate, // Corrected spelling
  setTasks,
  goals,
  handleSetRecurringTask,
  settings = { weekStartsOn: 'Mon' }, // Default settings
}) => {
  const [editedTask, setEditedTask] = useState(null);
  const [showAdvanced, setShowAdvanced] = useState(false);
  const [setEndDate, setSetEndDate] = useState(false);
  const [showDeleteOptions, setShowDeleteOptions] = useState(false);
  const [deleteOption, setDeleteOption] = useState('');
  const [selectedWeekdays, setSelectedWeekdays] = useState([]);

  // For selecting multiple dates via calendar
  const [selectedDates, setSelectedDates] = useState([]);

  // Reminder scope options for recurring tasks
  const [showReminderScopeOptions, setShowReminderScopeOptions] = useState(
    false
  );
  const [reminderScopeOption, setReminderScopeOption] = useState('');

  // State for new reminder inputs
  const [newReminderOption, setNewReminderOption] = useState('');
  const [newCustomReminder, setNewCustomReminder] = useState('');

  // New state variables for shift functionality
  const [isShift, setIsShift] = useState(false);
  const [shiftDuration, setShiftDuration] = useState('');
  const [shiftLetter, setShiftLetter] = useState('');

  // State for monthly recurrence options
  const [repeatOnLastDayOfMonth, setRepeatOnLastDayOfMonth] = useState(false);

  // Helper function to format date as 'YYYY-MM-DD'
  const getDateString = (date) => date.toISOString().split('T')[0];

  // Keep editedTask.dates in sync with selectedDates
  useEffect(() => {
    setEditedTask((prevTask) => ({
      ...prevTask,
      dates: selectedDates.map((date) => getDateString(date)),
    }));
  }, [selectedDates]);

  useEffect(() => {
    const formattedDates = task.dates || [];
    setEditedTask({
      ...task,
      dates: formattedDates,
      reminders: task.reminders || [],
    });

    setSelectedDates(
      formattedDates.map((dateStr) => {
        const date = new Date(dateStr);
        date.setHours(0, 0, 0, 0); // Ensure time is set to midnight
        return date;
      })
    );

    if (task.recurrence === 'weekly') {
      const originalDay = new Date(task.dates[0]).getDay();
      setSelectedWeekdays([originalDay]);
    }

    if (task.until) {
      setSetEndDate(true);
    }
    if (task.selectedWeekdays) {
      setSelectedWeekdays(task.selectedWeekdays);
    } else {
      setSelectedWeekdays([]);
    }

    // Initialize shift-related state variables
    setIsShift(task.isShift || false);
    setShiftDuration(task.shiftDuration || '');
    setShiftLetter(task.shiftLetter || '');

    // Initialize repeat on last day of month
    setRepeatOnLastDayOfMonth(task.repeatOnLastDayOfMonth || false);
  }, [task]);

  // Function to generate recurrence summary
  const getRecurrenceSummary = (task) => {
    if (!task.recurrence) return '';

    const untilDate = task.until ? new Date(task.until) : null;
    const untilString = untilDate
      ? ` until ${untilDate.toLocaleDateString()}`
      : '';

    switch (task.recurrence) {
      case 'daily':
        return `Every day${untilString}`;
      case 'weekly':
        const recurrenceDate = selectedDates[0] || new Date(task.dates[0]);
        return `Every week on ${recurrenceDate.toLocaleDateString('en-US', {
          weekday: 'long',
        })}${untilString}`;
      case 'monthly':
        if (task.repeatOnLastDayOfMonth) {
          return `Every month on the last day${untilString}`;
        } else {
          return `Every month on day ${new Date(task.dates[0]).getDate()}${untilString}`;
        }
      case 'yearly':
        return `Every year on ${new Date(task.dates[0]).toLocaleDateString(
          'en-US',
          {
            month: 'long',
            day: 'numeric',
          }
        )}${untilString}`;
      case 'custom':
        const weekdaysMap = {
          0: 'Sunday',
          1: 'Monday',
          2: 'Tuesday',
          3: 'Wednesday',
          4: 'Thursday',
          5: 'Friday',
          6: 'Saturday',
        };
        const days = task.selectedWeekdays
          .sort()
          .map((day) => weekdaysMap[day])
          .join(', ');
        return `Every ${days}${untilString}`;
      default:
        return '';
    }
  };

  // Function to schedule notifications
  const scheduleNotification = async (task) => {
    if (task.reminders && task.reminders.length > 0) {
      for (let i = 0; i < task.reminders.length; i++) {
        let reminderDateTime;
        const reminder = task.reminders[i];

        if (reminder.type === 'custom') {
          reminderDateTime = new Date(reminder.datetime);
        } else {
          // Calculate based on task time and date
          if (!task.time) continue; // Cannot schedule non-custom reminder without task time
          const taskDateTime = new Date(`${task.dates[0]}T${task.time}`);
          reminderDateTime = new Date(taskDateTime);
          switch (reminder.type) {
            case 'atEventTime':
              // reminderDateTime is the same as taskDateTime
              break;
            case '10minBefore':
              reminderDateTime.setMinutes(reminderDateTime.getMinutes() - 10);
              break;
            case '30minBefore':
              reminderDateTime.setMinutes(reminderDateTime.getMinutes() - 30);
              break;
            case '1hrBefore':
              reminderDateTime.setHours(reminderDateTime.getHours() - 1);
              break;
            case '1dayBefore':
              reminderDateTime.setDate(reminderDateTime.getDate() - 1);
              break;
            case '2daysBefore':
              reminderDateTime.setDate(reminderDateTime.getDate() - 2);
              break;
            default:
              break;
          }
        }
        // Generate unique notification ID
        const notificationId = parseInt(
          task.id.toString().replace('.', '') + i.toString()
        );
        await LocalNotifications.schedule({
          notifications: [
            {
              title: 'Task Reminder',
              body: task.title,
              id: notificationId,
              schedule: { at: reminderDateTime },
              sound: settings && settings.sound ? 'default' : null,
            },
          ],
        });
      }
    }
  };

  // Function to cancel scheduled notifications
  const cancelNotification = async (task) => {
    if (task.reminders && task.reminders.length > 0) {
      for (let i = 0; i < task.reminders.length; i++) {
        const notificationId = parseInt(
          task.id.toString().replace('.', '') + i.toString()
        );
        await LocalNotifications.cancel({
          notifications: [{ id: notificationId }],
        });
      }
    }
  };

  const handleAddReminder = () => {
    const newReminder = {
      type: newReminderOption,
    };
    if (newReminderOption === 'custom') {
      newReminder.datetime = newCustomReminder;
    }
    setEditedTask((prevTask) => ({
      ...prevTask,
      reminders: [...prevTask.reminders, newReminder],
    }));
    // Reset the inputs
    setNewReminderOption('');
    setNewCustomReminder('');
  };

  const handleDeleteReminder = (index) => {
    setEditedTask((prevTask) => {
      const updatedReminders = [...prevTask.reminders];
      updatedReminders.splice(index, 1);
      return {
        ...prevTask,
        reminders: updatedReminders,
      };
    });
  };

  const handleSave = async () => {
    // Ensure the task title is not empty
    if (!editedTask.title || editedTask.title.trim() === '') {
      alert('Task title cannot be empty.');
      return;
    }

    const updatedTask = {
      ...editedTask,
      dates: editedTask.recurrence
        ? editedTask.dates // Keep the original dates if recurring
        : selectedDates.map((date) => getDateString(date)),
      isShift,
      shiftDuration,
      shiftLetter,
      selectedWeekdays,
      until: setEndDate ? editedTask.until : null,
      repeatOnLastDayOfMonth,
    };

    // Update the task in the tasks list
    setTasks((prevTasks) => {
      const existingTaskIndex = prevTasks.findIndex(
        (t) => t.id === updatedTask.id
      );
      if (existingTaskIndex !== -1) {
        const newTasks = [...prevTasks];
        newTasks[existingTaskIndex] = updatedTask;
        return newTasks;
      } else {
        return [...prevTasks, updatedTask];
      }
    });

    // Handle recurring tasks
    if (updatedTask.recurrence) {
      await handleSetRecurringTask(updatedTask);
    } else {
      // For non-recurring tasks, schedule notifications
      await scheduleNotification(updatedTask);
    }

    onClose();
  };

  const handleDelete = () => {
    // Cancel notification when deleting a task
    cancelNotification(editedTask);

    if (editedTask.recurrence) {
      setShowDeleteOptions(true);
    } else {
      // Delete only the selected task
      setTasks((prevTasks) => prevTasks.filter((t) => t.id !== editedTask.id));
      onClose();
    }
  };

  const confirmDelete = () => {
    if (deleteOption === 'this') {
      // For deleting this occurrence, add the occurrenceDate to exceptions
      const dateString = occurrenceDate; // Use occurrenceDate
      setTasks((prevTasks) => {
        const newTasks = prevTasks.map((t) => {
          if (t.id === editedTask.id) {
            const updatedTask = { ...t };
            updatedTask.exceptions = updatedTask.exceptions || [];
            if (!updatedTask.exceptions.includes(dateString)) {
              updatedTask.exceptions.push(dateString);
            }
            return updatedTask;
          }
          return t;
        });
        return newTasks;
      });
    } else if (deleteOption === 'future') {
      // Delete this and future occurrences by setting 'until' date
      const untilDate = occurrenceDate; // Use occurrenceDate
      setTasks((prevTasks) => {
        const newTasks = prevTasks.map((t) => {
          if (t.id === editedTask.id) {
            const updatedTask = { ...t, until: untilDate };
            return updatedTask;
          }
          return t;
        });
        return newTasks;
      });
    } else if (deleteOption === 'all') {
      // Delete all occurrences
      setTasks((prevTasks) => prevTasks.filter((t) => t.id !== editedTask.id));
    }
    setShowDeleteOptions(false);
    onClose();
  };

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;

    const updatedValue = type === 'checkbox' ? checked : value;

    setEditedTask((prevTask) => ({
      ...prevTask,
      [name]: updatedValue,
    }));
  };

  const toggleAdvancedOptions = () => setShowAdvanced(!showAdvanced);

  const handleRecurrenceChange = (e) => {
    const { value } = e.target;
    const firstSelectedDate = selectedDates[0] || new Date();
    setEditedTask((prev) => ({
      ...prev,
      recurrence: value,
      selectedWeekdays:
        value === 'custom' ? [] : [firstSelectedDate.getDay()],
    }));
  };

  if (!editedTask) return null;

  
  return (
    <div
      className={`fixed inset-0 ${
        settings.darkMode
          ? 'bg-gray-900 bg-opacity-80'
          : 'bg-gray-500 bg-opacity-50'
      } flex justify-center items-center z-50`}
    >
      <div
        className={`${
          settings.darkMode ? 'bg-gray-800 text-white' : 'bg-white text-black'
        } p-4 rounded shadow-lg w-96 relative max-h-full overflow-y-auto`}
      >
        <h2 className="text-xl font-semibold mb-4">{title}</h2>

        {/* Task Title */}
        <label className="block text-sm font-bold mb-2">Task Title</label>
        <input
          type="text"
          name="title"
          value={editedTask.title}
          onChange={handleInputChange}
          className={`border rounded w-full p-2 mb-4 ${
            settings.darkMode
              ? 'bg-gray-700 text-white border-gray-600'
              : 'bg-white text-black border-gray-300'
          }`}
        />

        {/* Important Toggle */}
        <div className="mb-4">
          <label className="flex items-center">
            <input
              type="checkbox"
              name="important"
              checked={editedTask.important || false}
              onChange={handleInputChange}
              className="mr-2"
            />
            Mark as Important
          </label>
        </div>

        {/* Shift Toggle */}
        <div className="mb-4">
          <label className="flex items-center">
            <input
              type="checkbox"
              name="isShift"
              checked={isShift}
              onChange={(e) => setIsShift(e.target.checked)}
              className="mr-2"
            />
            Set as Shift
          </label>
        </div>

        {/* Shift Details */}
        {isShift && (
          <>
            {/* Shift Duration */}
            <label className="block text-sm font-bold mb-2">
              Shift Duration (hours)
            </label>
            <input
              type="number"
              name="shiftDuration"
              min="1"
              max="12"
              value={shiftDuration}
              onChange={(e) => setShiftDuration(e.target.value)}
              className={`border rounded w-full p-2 mb-4 ${
                settings.darkMode
                  ? 'bg-gray-700 text-white border-gray-600'
                  : 'bg-white text-black border-gray-300'
              }`}
            />

            {/* Shift Background Color */}
            <label className="block text-sm font-bold mb-2">
              Shift Background Color
            </label>
            <input
              type="color"
              name="backgroundColor"
              value={editedTask.backgroundColor || '#ffffff'}
              onChange={handleInputChange}
              className="w-full h-10 mb-4 p-0 border-0"
            />

            {/* Letter to Display */}
            <label className="block text-sm font-bold mb-2">
              Letter to Display on Calendar
            </label>
            <input
              type="text"
              name="shiftLetter"
              maxLength="1"
              value={shiftLetter}
              onChange={(e) => setShiftLetter(e.target.value)}
              className={`border rounded w-full p-2 mb-4 ${
                settings.darkMode
                  ? 'bg-gray-700 text-white border-gray-600'
                  : 'bg-white text-black border-gray-300'
              }`}
            />
          </>
        )}

        {/* Dates via Calendar or Recurrence Summary */}
        <label className="block text-sm font-bold mb-2">
          {editedTask.recurrence ? 'Recurrence' : 'Select Dates'}
        </label>
        {editedTask.recurrence ? (
          <div className="mt-2 mb-4">
            <div className="text-sm">
              {getRecurrenceSummary(editedTask)}
            </div>
          </div>
        ) : (
          <>
            <DayPicker
              mode="multiple"
              selected={selectedDates}
              onSelect={setSelectedDates}
              disabled={{ before: new Date() }}
              locale={enGB} // Use enGB locale to start week on Monday
              weekStartsOn={
                settings.weekStartsOn === 'Sun' ? 0 : 1
              } // Adjust week start
              styles={{
                day: {
                  fontSize: '0.875rem',
                },
              }}
            />
            <div className="mt-2 mb-4">
              <strong>Selected Dates:</strong>
              {selectedDates.length > 0 ? (
                <ul>
                  {selectedDates.map((date, index) => (
                    <li key={index}>{date.toLocaleDateString()}</li>
                  ))}
                </ul>
              ) : (
                <p>No dates selected.</p>
              )}
            </div>
          </>
        )}

        {/* Time */}
        {!isShift && (
          <>
            <label className="block text-sm font-bold mb-2">Time</label>
            <input
              type="time"
              name="time"
              value={editedTask.time || ''}
              onChange={handleInputChange}
              className={`border rounded w-full p-2 mb-4 ${
                settings.darkMode
                  ? 'bg-gray-700 text-white border-gray-600'
                  : 'bg-white text-black border-gray-300'
              }`}
            />
          </>
        )}

        {/* Goal Assignment */}
        <label className="block text-sm font-bold mb-2">
          Assign to Goal
        </label>
        <select
          name="goalId"
          value={editedTask.goalId || ''}
          onChange={(e) =>
            setEditedTask({ ...editedTask, goalId: e.target.value })
          }
          className={`border rounded w-full p-2 mb-4 ${
            settings.darkMode
              ? 'bg-gray-700 text-white border-gray-600'
              : 'bg-white text-black border-gray-300'
          }`}
        >
          <option value="">No Goal</option>
          {goals.map((goal) => (
            <option key={goal.id} value={goal.id}>
              {goal.title}
            </option>
          ))}
        </select>

        {/* Toggle Advanced Options */}
        <div className="mb-4">
          <button
            onClick={toggleAdvancedOptions}
            className="text-blue-500 underline"
          >
            {showAdvanced ? 'Hide Advanced Options' : 'Show Advanced Options'}
          </button>
        </div>

        {showAdvanced && (
          <>
            {/* Set Recurrence */}
            <label className="block text-sm font-bold mb-2">
              Set Recurrence
            </label>
            <select
              name="recurrence"
              value={editedTask.recurrence || ''}
              onChange={handleRecurrenceChange}
              className={`border rounded w-full p-2 mb-4 ${
                settings.darkMode
                  ? 'bg-gray-700 text-white border-gray-600'
                  : 'bg-white text-black border-gray-300'
              }`}
            >
              <option value="">No Recurrence</option>
              <option value="daily">Daily</option>
              <option value="weekly">Weekly</option>
              <option value="monthly">Monthly</option>
              <option value="yearly">Yearly</option>
              <option value="custom">Custom</option>
            </select>

            {/* Weekly Recurrence - Show day of week */}
            {editedTask.recurrence === 'weekly' && (
              <div className="mb-4">
                <p>
                  This task will repeat every{' '}
                  {new Date(editedTask.dates[0]).toLocaleDateString('en-US', {
                    weekday: 'long',
                  })}
                  .
                </p>
              </div>
            )}

            {/* Monthly Recurrence Options */}
            {editedTask.recurrence === 'monthly' && (
              <div className="mb-4">
                <label className="flex items-center">
                  <input
                    type="checkbox"
                    checked={repeatOnLastDayOfMonth}
                    onChange={(e) =>
                      setRepeatOnLastDayOfMonth(e.target.checked)
                    }
                    className="mr-2"
                  />
                  Repeat on the last day of each month
                </label>
              </div>
            )}

            {/* Custom Recurrence */}
            {editedTask.recurrence === 'custom' && (
              <div className="mb-4">
                <label className="block mb-1">Select Weekdays</label>
                <div className="flex flex-wrap">
                  {['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'].map(
                    (day, index) => (
                      <label
                        key={day}
                        className="flex items-center mr-4 mb-2"
                      >
                        <input
                          type="checkbox"
                          name="selectedWeekdays"
                          value={index}
                          checked={selectedWeekdays.includes(index)}
                          onChange={(e) => {
                            const value = parseInt(e.target.value);
                            if (e.target.checked) {
                              setSelectedWeekdays([...selectedWeekdays, value]);
                            } else {
                              setSelectedWeekdays(
                                selectedWeekdays.filter((d) => d !== value)
                              );
                            }
                          }}
                          className="mr-1"
                        />
                        {day}
                      </label>
                    )
                  )}
                </div>
              </div>
            )}

            {/* Set End Date Toggle */}
            {editedTask.recurrence && (
              <div className="mb-4">
                <label className="flex items-center">
                  <input
                    type="checkbox"
                    checked={setEndDate}
                    onChange={() => setSetEndDate(!setEndDate)}
                    className="mr-2"
                  />
                  Set End Date
                </label>
              </div>
            )}

            {/* End Date Input */}
            {setEndDate && editedTask.recurrence && (
              <div className="mb-4">
                <label className="block text-sm font-bold mb-2">
                  End Recurrence On
                </label>
                <input
                  type="date"
                  name="until"
                  value={editedTask.until || ''}
                  onChange={handleInputChange}
                  className={`border rounded w-full p-2 ${
                    settings.darkMode
                      ? 'bg-gray-700 text-white border-gray-600'
                      : 'bg-white text-black border-gray-300'
                  }`}
                />
              </div>
            )}

            {/* Multiple Reminders */}
            <label className="block text-sm font-bold mb-2">
              Add Reminder
            </label>
            <select
              name="newReminderOption"
              value={newReminderOption}
              onChange={(e) => setNewReminderOption(e.target.value)}
              className={`border rounded w-full p-2 mb-2 ${
                settings.darkMode
                  ? 'bg-gray-700 text-white border-gray-600'
                  : 'bg-white text-black border-gray-300'
              }`}
            >
              <option value="">Select Reminder</option>
              <option value="atEventTime">At Event Time</option>
              <option value="10minBefore">10 Minutes Before</option>
              <option value="30minBefore">30 Minutes Before</option>
              <option value="1hrBefore">1 Hour Before</option>
              <option value="1dayBefore">1 Day Before</option>
              <option value="2daysBefore">2 Days Before</option>
              <option value="custom">Custom</option>
            </select>

            {/* Show datetime-local input if 'custom' is selected */}
            {newReminderOption === 'custom' && (
              <input
                type="datetime-local"
                name="newCustomReminder"
                value={newCustomReminder}
                onChange={(e) => setNewCustomReminder(e.target.value)}
                className={`border rounded w-full p-2 mb-2 ${
                  settings.darkMode
                    ? 'bg-gray-700 text-white border-gray-600'
                    : 'bg-white text-black border-gray-300'
                }`}
              />
            )}

            <button
              onClick={handleAddReminder}
              className="bg-blue-500 text-white p-2 rounded mb-4"
              disabled={
                !newReminderOption ||
                (newReminderOption === 'custom' && !newCustomReminder)
              }
            >
              Add Reminder
            </button>

            {/* List of Reminders */}
            {editedTask.reminders && editedTask.reminders.length > 0 && (
              <div className="mb-4">
                <strong>Reminders:</strong>
                <ul>
                  {editedTask.reminders.map((reminder, index) => (
                    <li
                      key={index}
                      className="flex justify-between items-center"
                    >
                      <span>
                        {reminder.type === 'custom'
                          ? `Custom: ${new Date(
                              reminder.datetime
                            ).toLocaleString()}`
                          : reminder.type}
                      </span>
                      <button
                        onClick={() => handleDeleteReminder(index)}
                        className="text-red-500 underline"
                      >
                        Delete
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </>
        )}

        {/* Save and Delete Buttons */}
        <div className="flex justify-end space-x-2">
          <button
            onClick={handleDelete}
            className="bg-red-500 text-white p-2 rounded"
          >
            Delete
          </button>
          <button
            onClick={onClose}
            className={`p-2 rounded ${
              settings.darkMode
                ? 'bg-gray-700 text-white'
                : 'bg-gray-300 text-black'
            }`}
          >
            Cancel
          </button>
          <button
            onClick={handleSave}
            className="bg-green-500 text-white p-2 rounded"
          >
            Save
          </button>
        </div>

        {/* Delete Options Modal */}
        {showDeleteOptions && (
          <div
            className={`absolute inset-0 ${
              settings.darkMode
                ? 'bg-gray-900 bg-opacity-80'
                : 'bg-gray-500 bg-opacity-50'
            } flex justify-center items-center`}
          >
            <div
              className={`${
                settings.darkMode
                  ? 'bg-gray-800 text-white'
                  : 'bg-white text-black'
              } p-4 rounded shadow-lg w-80`}
            >
              <h3 className="text-lg font-semibold mb-4">
                Delete Recurring Task
              </h3>
              <p className="mb-4">Do you want to delete:</p>
              <div className="mb-4">
                <label className="flex items-center">
                  <input
                    type="radio"
                    name="deleteOption"
                    value="this"
                    onChange={(e) => setDeleteOption(e.target.value)}
                    className="mr-2"
                  />
                  Only this occurrence
                </label>
                <label className="flex items-center">
                  <input
                    type="radio"
                    name="deleteOption"
                    value="future"
                    onChange={(e) => setDeleteOption(e.target.value)}
                    className="mr-2"
                  />
                  This and future occurrences
                </label>
                <label className="flex items-center">
                  <input
                    type="radio"
                    name="deleteOption"
                    value="all"
                    onChange={(e) => setDeleteOption(e.target.value)}
                    className="mr-2"
                  />
                  All occurrences
                </label>
              </div>
              <div className="flex justify-end space-x-2">
                <button
                  onClick={() => setShowDeleteOptions(false)}
                  className={`p-2 rounded ${
                    settings.darkMode
                      ? 'bg-gray-700 text-white'
                      : 'bg-gray-300 text-black'
                  }`}
                >
                  Cancel
                </button>
                <button
                  onClick={confirmDelete}
                  className="bg-red-500 text-white p-2 rounded"
                  disabled={!deleteOption}
                >
                  Delete
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Reminder Scope Options Modal */}
        {showReminderScopeOptions && (
          <div
            className={`absolute inset-0 ${
              settings.darkMode
                ? 'bg-gray-900 bg-opacity-80'
                : 'bg-gray-500 bg-opacity-50'
            } flex justify-center items-center`}
          >
            <div
              className={`${
                settings.darkMode
                  ? 'bg-gray-800 text-white'
                  : 'bg-white text-black'
              } p-4 rounded shadow-lg w-80`}
            >
              <h3 className="text-lg font-semibold mb-4">
                Apply Reminder to Recurring Tasks
              </h3>
              <p className="mb-4">Do you want to set the reminder for:</p>
              <div className="mb-4">
                <label className="flex items-center">
                  <input
                    type="radio"
                    name="reminderScopeOption"
                    value="all"
                    onChange={(e) =>
                      setReminderScopeOption(e.target.value)
                    }
                    className="mr-2"
                  />
                  All occurrences
                </label>
              </div>
              <div className="flex justify-end space-x-2">
                <button
                  onClick={() => setShowReminderScopeOptions(false)}
                  className={`p-2 rounded ${
                    settings.darkMode
                      ? 'bg-gray-700 text-white'
                      : 'bg-gray-300 text-black'
                  }`}
                >
                  Cancel
                </button>
                <button
                  onClick={() => setShowReminderScopeOptions(false)}
                  className="bg-green-500 text-white p-2 rounded"
                  disabled={!reminderScopeOption}
                >
                  Apply
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Modal;