// LogView.js

import React, { useState, useEffect, useRef } from 'react';
import {
  DragDropContext,
  Droppable,
  Draggable,
} from '@hello-pangea/dnd';
import {
  GripVertical,
  Clock,
  ChevronLeft,
  ChevronRight,
  X as CloseIcon,
} from 'lucide-react';
import Modal from './Modal';

import typewriterSound from '../sounds/typewriter.wav';
import { DayPicker } from 'react-day-picker';
import 'react-day-picker/dist/style.css';

// Import the en-GB locale to start the week on Monday
import enGB from 'date-fns/locale/en-GB';

// Import helper functions
import { getCurrentDate, getDateString } from '../utils/helpers';

const LogView = ({
  tasks,
  setTasks,
  goals,
  setGoals,
  handleSetRecurringTask,
  settings,
  daysMarkedAsDone = [],
  streakSaversUsed = [],
  setIsLogViewOpen,
}) => {
const [modalTask, setModalTask] = useState(null);
const [modalOccurrenceDate, setModalOccurrenceDate] = useState(null);
const [isModalOpen, setIsModalOpen] = useState(false);

const openEditModal = (task, occurrenceDate) => {
  setModalTask(task);
  setModalOccurrenceDate(occurrenceDate);
  setIsModalOpen(true);
};

const closeModal = () => {
  setIsModalOpen(false);
  setModalTask(null);
  setModalOccurrenceDate(null);
};

  const [postItNote, setPostItNote] = useState(() => {
    // Load the post-it note content from localStorage on initial render
    return localStorage.getItem('postItNote') || '';
  });

  const [selectedDate, setSelectedDate] = useState(getCurrentDate());
  const [showMonthPicker, setShowMonthPicker] = useState(false);

  const typewriterSoundRef = useRef(null);

  const dayRefs = useRef({}); // To hold references to day containers
  const textareaRef = useRef(null);

  // Helper function to get the month name
  const getMonthName = (date) => {
    return date.toLocaleDateString('en-US', {
      month: 'long',
      year: 'numeric',
    });
  };

  const addNewTaskForDate = (date) => {
    const dateString = getDateString(date);
    const tasksForDate = tasks.filter(
      (task) => doesTaskOccurOnDate(task, date) && !task.isShift
    );
    const newTask = {
      id: Date.now().toString(),
      title: 'New Task',
      completed: false,
      dates: [dateString],
      time: '',
      recurrence: null,
      label: '',
      goalId: '',
      order: {
        [dateString]: tasksForDate.length, // Set order to the end of the list for that date
      },
      completedDates: [], // Initialize for recurring tasks
    };
    setTasks((prevTasks) => [...prevTasks, newTask]);
    openEditModal(newTask);
  };

  const toggleTaskCompletion = (taskId, dateString) => {
    setTasks((prevTasks) => {
      const updatedTasks = prevTasks.map((task) => {
        if (task.id === taskId) {
          if (task.recurrence) {
            // Handle recurring tasks
            const completedDates = task.completedDates || [];
            const isCompleted = completedDates.includes(dateString);

            const updatedCompletedDates = isCompleted
              ? completedDates.filter((d) => d !== dateString)
              : [...completedDates, dateString];

            const updatedTask = {
              ...task,
              completedDates: updatedCompletedDates,
            };

            if (!isCompleted) {
              playTypewriterSound();
            }

            return updatedTask;
          } else {
            // Handle non-recurring tasks
            const updatedTask = {
              ...task,
              completed: !task.completed,
            };

            if (updatedTask.completed) {
              playTypewriterSound();
            }

            return updatedTask;
          }
        }
        return task;
      });

      const completedTask = updatedTasks.find((task) => task.id === taskId);

      if (completedTask && completedTask.goalId && goals) {
        const relatedGoal = goals.find(
          (goal) => goal.id === completedTask.goalId
        );

        if (relatedGoal) {
          let newProgress = 0;
          if (completedTask.recurrence) {
            // Count the number of times the task has been completed
            newProgress = updatedTasks.reduce((count, t) => {
              if (t.goalId === completedTask.goalId && t.completedDates) {
                count += t.completedDates.length;
              }
              return count;
            }, 0);
          } else {
            // Count the number of completed tasks assigned to the goal
            newProgress = updatedTasks.filter(
              (t) => t.goalId === completedTask.goalId && t.completed
            ).length;
          }

          setGoals((prevGoals) =>
            prevGoals.map((g) =>
              g.id === relatedGoal.id ? { ...g, progress: newProgress } : g
            )
          );
        }
      }

      return updatedTasks;
    });
  };

  // Helper function to check if a task occurs on a specific date
  const doesTaskOccurOnDate = (task, date) => {
    const dateString = getDateString(date);

    // Check if the date is in the task's exceptions
    if (task.exceptions && task.exceptions.includes(dateString)) {
      return false;
    }

    // Check if the date is in the task's dates array
    if (task.dates && task.dates.includes(dateString)) {
      return true;
    }

    // Handle recurring tasks
    if (task.recurrence) {
      const taskStartDate = new Date(task.dates[0]);
      taskStartDate.setHours(0, 0, 0, 0); // Ensure time is set to midnight
      const taskEndDate = task.until ? new Date(task.until) : null;

      // If task.until is set, and date is after until date, return false
      if (taskEndDate && date > taskEndDate) {
        return false;
      }

      // If date is before task start date, return false
      if (date < taskStartDate) {
        return false;
      }

      switch (task.recurrence) {
        case 'daily':
          return true; // Occurs every day
        case 'weekly':
          // Occurs on the same weekday as the task's start date
          return date.getDay() === taskStartDate.getDay();
        case 'monthly':
          if (task.repeatOnLastDayOfMonth) {
            // Check if the date is the last day of the month
            const nextDay = new Date(date);
            nextDay.setDate(date.getDate() + 1);
            return nextDay.getDate() === 1;
          } else {
            // Occurs on the same day of the month as the task's start date
            return date.getDate() === taskStartDate.getDate();
          }
        case 'yearly':
          // Occurs on the same month and day as the task's start date
          return (
            date.getDate() === taskStartDate.getDate() &&
            date.getMonth() === taskStartDate.getMonth()
          );
        case 'custom':
          if (task.selectedWeekdays) {
            // Occurs on the selected weekdays
            return task.selectedWeekdays.includes(date.getDay());
          }
          return false;
        default:
          return false;
      }
    }

    return false;
  };

  const onDragEnd = (result) => {
    const { source, destination, draggableId } = result;

    // Dropped outside the list
    if (!destination) return;

    // If dropped to the same place
    if (
      source.droppableId === destination.droppableId &&
      source.index === destination.index
    ) {
      return;
    }

    // Parse taskId and dateString from draggableId (format "taskId::dateString")
    const [taskId, dateString] = draggableId.split('::');
    const task = tasks.find((t) => t.id === taskId);

    if (!task) return;

    setTasks((prevTasks) => {
      const updatedTasks = prevTasks.map((t) => ({ ...t }));

      const taskIndex = updatedTasks.findIndex((t) => t.id === taskId);
      const taskToUpdate = updatedTasks[taskIndex];

      // Ensure order is an object
      if (!taskToUpdate.order || typeof taskToUpdate.order !== 'object') {
        taskToUpdate.order = {};
      }

      if (source.droppableId === destination.droppableId) {
        // Reordering within the same date
        const dateTasks = updatedTasks
          .filter((t) => doesTaskOccurOnDate(t, new Date(source.droppableId)))
          .sort(
            (a, b) =>
              (a.order?.[source.droppableId] || 0) -
              (b.order?.[source.droppableId] || 0)
          );

        const [movedTask] = dateTasks.splice(source.index, 1);
        dateTasks.splice(destination.index, 0, movedTask);

        // Update the order
        dateTasks.forEach((t, idx) => {
          if (!t.order || typeof t.order !== 'object') {
            t.order = {};
          }
          t.order[source.droppableId] = idx;
        });
      } else {
        // Moving to a different date
        // Update dates array for the task
        if (taskToUpdate.recurrence) {
          // For recurring tasks
          // Add the destination date to exceptions if it doesn't occur there naturally
          if (!doesTaskOccurOnDate(taskToUpdate, new Date(destination.droppableId))) {
            taskToUpdate.dates = taskToUpdate.dates || [];
            taskToUpdate.dates.push(destination.droppableId);
          }

          // Add the source date to exceptions if needed
          if (doesTaskOccurOnDate(taskToUpdate, new Date(source.droppableId))) {
            taskToUpdate.exceptions = taskToUpdate.exceptions || [];
            if (!taskToUpdate.exceptions.includes(source.droppableId)) {
              taskToUpdate.exceptions.push(source.droppableId);
            }
          }
        } else {
          // For non-recurring tasks
          // Remove the source date
          taskToUpdate.dates = taskToUpdate.dates.filter(
            (date) => date !== source.droppableId
          );
          // Add the destination date
          if (!taskToUpdate.dates.includes(destination.droppableId)) {
            taskToUpdate.dates.push(destination.droppableId);
          }
        }

        // Update order for both source and destination dates
        const sourceDateTasks = updatedTasks
          .filter((t) => doesTaskOccurOnDate(t, new Date(source.droppableId)))
          .sort(
            (a, b) =>
              (a.order?.[source.droppableId] || 0) -
              (b.order?.[source.droppableId] || 0)
          );

        sourceDateTasks.forEach((t, idx) => {
          if (!t.order || typeof t.order !== 'object') {
            t.order = {};
          }
          t.order[source.droppableId] = idx;
        });

        const destinationDateTasks = updatedTasks
          .filter((t) =>
            doesTaskOccurOnDate(t, new Date(destination.droppableId))
          )
          .sort(
            (a, b) =>
              (a.order?.[destination.droppableId] || 0) -
              (b.order?.[destination.droppableId] || 0)
          );

        destinationDateTasks.forEach((t, idx) => {
          if (!t.order || typeof t.order !== 'object') {
            t.order = {};
          }
          t.order[destination.droppableId] = idx;
        });
      }

      return updatedTasks;
    });
  };

  const playTypewriterSound = () => {
    if (settings.sound && typewriterSoundRef.current) {
      typewriterSoundRef.current.currentTime = 0;
      typewriterSoundRef.current.play();
    }
  };

  // Helper function to get goal details
  const getGoalDetails = (goalId) => {
    if (!goals || !Array.isArray(goals)) return null;
    return goals.find((goal) => goal.id === goalId);
  };

  // Helper function to format time
  const formatTime = (time) => {
    if (!time) return '';
    const [hour, minute] = time.split(':');
    const date = new Date();
    date.setHours(hour, minute);
    return date.toLocaleTimeString([], {
      hour: 'numeric',
      minute: '2-digit',
    });
  };

  // Handle month picker
  const handleMonthChange = (date) => {
    setSelectedDate(new Date(date));
    setShowMonthPicker(false);
  };

  useEffect(() => {
    localStorage.setItem('postItNote', postItNote);
  }, [postItNote]);

  // Scroll to today's date on component mount
  useEffect(() => {
    const todayString = getDateString(getCurrentDate());
    if (dayRefs.current[todayString]) {
      dayRefs.current[todayString].scrollIntoView({
        behavior: 'smooth',
      });
    }
  }, [selectedDate]);

  useEffect(() => {
    // Adjust the textarea height when postItNote changes
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto'; // Reset the height
      textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`; // Set it to the scrollHeight
    }
  }, [postItNote]);

  const getWeekDates = (selectedDate) => {
    const weekStartsOn = settings?.weekStartsOn === 'Sun' ? 0 : 1; // 0 for Sunday, 1 for Monday
    const startOfWeek = new Date(selectedDate);
    const dayOfWeek = startOfWeek.getDay();
    const diff = (dayOfWeek < weekStartsOn ? 7 : 0) + dayOfWeek - weekStartsOn;
    startOfWeek.setDate(startOfWeek.getDate() - diff);

    const weekDates = Array.from({ length: 7 }, (_, i) => {
      const date = new Date(startOfWeek);
      date.setDate(startOfWeek.getDate() + i);
      return date;
    });

    return weekDates;
  };

  // Custom DayContent component for DayPicker to show important tasks and background colors
  const CustomDayContent = (day) => {
    const dateString = getDateString(day.date);
    const dayTasks = tasks.filter((task) =>
      doesTaskOccurOnDate(task, day.date)
    );

    const importantTaskExists = dayTasks.some((task) => task.important);
    const backgroundTasks = dayTasks.filter((task) => task.backgroundColor);

    return (
      <div className="relative">
        {backgroundTasks.map((task, index) => (
          <div
            key={index}
            className="absolute inset-0 opacity-20"
            style={{ backgroundColor: task.backgroundColor }}
          ></div>
        ))}
        <div className="relative z-10">{day.date.getDate()}</div>
        {importantTaskExists && (
          <div className="absolute bottom-0 right-0 w-2 h-2 bg-red-500 rounded-full"></div>
        )}
      </div>
    );
  };

  const formatWeekTitle = () => {
    const weekDates = getWeekDates(selectedDate);
    const startDate = weekDates[0];
    const endDate = weekDates[6];

    // Validate dates
    if (!(startDate instanceof Date) || isNaN(startDate))
      return 'Invalid Date';
    if (!(endDate instanceof Date) || isNaN(endDate)) return 'Invalid Date';

    const startDay = startDate.getDate();
    const endDay = endDate.getDate();
    const monthName = startDate.toLocaleDateString('en-US', { month: 'long' });

    return `${startDay} to ${endDay} ${monthName}`;
  };

  return (
    <div
      className={`p-2 ${
        settings.darkMode ? 'bg-gray-900 text-white' : 'bg-gray-100 text-black'
      }`}
    >
      {/* Header with Month Title and Close Button */}
      <div className="flex items-center justify-between mb-4">
        <h1
          className="text-xl font-bold cursor-pointer"
          onClick={() => setShowMonthPicker(true)}
        >
          {getMonthName(selectedDate)}
        </h1>
        <button
          onClick={() => setIsLogViewOpen(false)}
          className="p-1 rounded-full hover:bg-gray-200"
        >
          <CloseIcon size={24} />
        </button>
      </div>
      
      {/* Month Picker Modal */}
      {showMonthPicker && (
        <div
          className={`fixed inset-0 ${
            settings.darkMode
              ? 'bg-gray-900 bg-opacity-80'
              : 'bg-gray-500 bg-opacity-50'
          } flex justify-center items-center z-50`}
        >
          <div
            className={`${
              settings.darkMode ? 'bg-gray-800' : 'bg-white'
            } p-4 rounded shadow-lg`}
          >
            <DayPicker
              mode="single"
              selected={selectedDate}
              onSelect={handleMonthChange}
              fromYear={2000}
              toYear={2030}
              captionLayout="dropdown"
              onMonthChange={(month) => setSelectedDate(new Date(month))}
              components={{
                DayContent: CustomDayContent,
              }}
              locale={enGB} // Set week to start on Monday
            />
            <button
              onClick={() => setShowMonthPicker(false)}
              className="mt-2 bg-blue-500 text-white p-2 rounded"
            >
              Close
            </button>
          </div>
        </div>
      )}

      {/* Weekly Navigation */}
      <div
        className={`bg-white rounded-lg shadow p-2 mb-4 ${
          settings.darkMode ? 'bg-gray-800' : 'bg-white'
        }`}
      >
        <div className="flex justify-between items-center">
          <button
            onClick={() =>
              setSelectedDate(
                new Date(selectedDate.setDate(selectedDate.getDate() - 7))
              )
            }
            className="p-1 rounded-full hover:bg-gray-200"
          >
            <ChevronLeft size={24} />
          </button>
          <span className="font-bold text-md">{formatWeekTitle()}</span>
          <button
            onClick={() =>
              setSelectedDate(
                new Date(selectedDate.setDate(selectedDate.getDate() + 7))
              )
            }
            className="p-1 rounded-full hover:bg-gray-200"
          >
            <ChevronRight size={24} />
          </button>
        </div>
      </div>
      
      {/* Drag and Drop Context */}
      <DragDropContext onDragEnd={onDragEnd}>
        {getWeekDates(selectedDate).map((date, index) => {
          const dateString = getDateString(date);
          let dateTasks = tasks
            .filter((task) => doesTaskOccurOnDate(task, date))
            .sort(
              (a, b) =>
                (a.order?.[dateString] || 0) - (b.order?.[dateString] || 0)
            );

          const isToday = dateString === getDateString(getCurrentDate());

          const shiftTasks = dateTasks.filter((task) => task.isShift);
          const nonShiftTasks = dateTasks.filter((task) => !task.isShift);

          dateTasks = nonShiftTasks;

         

          return (
            <div
              key={index}
              className="mb-4"
              ref={(el) => (dayRefs.current[dateString] = el)}
            >
              <div
                className={`font-bold text-sm mb-2 flex justify-between items-center ${
                  isToday ? 'text-blue-500' : ''
                }`}
              >
                <div className="flex items-center">
                  <span>{date.toDateString()}</span>
                  {shiftTasks.map((shiftTask) => (
                    <div
                      key={shiftTask.id}
                      className="ml-2 px-2 py-1 rounded cursor-pointer"
                      style={{
                        backgroundColor: shiftTask.backgroundColor || '#ccc',
                      }}
                      onClick={() => openEditModal(shiftTask)}
                    >
                      {shiftTask.title}
                    </div>
                  ))}
                </div>
                {/* Add the "+" button here */}
                <button
                  onClick={() => addNewTaskForDate(date)}
                  className="p-1 bg-blue-500 text-white rounded-full"
                >
                  +
                </button>
              </div>
              <Droppable droppableId={dateString}>
                {(provided, snapshot) => (
                  <ul
                    {...provided.droppableProps}
                    ref={provided.innerRef}
                    className={`min-h-[50px] p-2 rounded-lg shadow ${
                      snapshot.isDraggingOver
                        ? 'bg-blue-100'
                        : settings.darkMode
                        ? 'bg-gray-800'
                        : 'bg-white'
                    }`}
                    style={{ minHeight: '50px' }}
                  >
                    {dateTasks.length === 0 && (
                      <li className="text-center text-gray-500 py-2">
                        {/* Empty space to allow drop */}
                        Drop tasks here
                      </li>
                    )}
                    {dateTasks.map((task, idx) => {
                      const goalDetails = getGoalDetails(task.goalId);
                      const isCompleted = task.recurrence
                        ? (task.completedDates || []).includes(dateString)
                        : task.completed;
                      return (
                        <Draggable
                          key={`${task.id}::${dateString}`}
                          draggableId={`${task.id}::${dateString}`}
                          index={idx}
                        >
                          {(provided) => (
                            <li
                              {...provided.draggableProps}
                              ref={provided.innerRef}
                              className="border p-2 rounded w-full mb-2 flex justify-between items-center"
                            >
                              <div
                                className="flex items-center"
                                onDoubleClick={() => openEditModal(task, dateString)}

                              >
                                <input
                                  type="checkbox"
                                  checked={isCompleted}
                                  onChange={() =>
                                    toggleTaskCompletion(task.id, dateString)
                                  }
                                  className="mr-2"
                                />
                                <span className="text-sm">
                                  {task.time && (
                                    <span className="mr-1">
                                      {formatTime(task.time)}
                                    </span>
                                  )}
                                  {task.title}
                                  {goalDetails && (
                                    <span className="ml-1 text-xs text-gray-500">
                                      ({goalDetails.title})
                                    </span>
                                  )}
                                  {task.important && (
                                    <span className="ml-1 text-red-500 font-bold">
                                      *
                                    </span>
                                  )}
                                </span>
                              </div>
                              <div className="flex items-center">
                                {task.reminders &&
                                  task.reminders.length > 0 && (
                                    <Clock
                                      size={16}
                                      className="inline mr-1"
                                    />
                                  )}
                                {goalDetails && goalDetails.color && (
                                  <div
                                    className="w-2 h-2 rounded-full mr-1"
                                    style={{
                                      backgroundColor: goalDetails.color,
                                    }}
                                  ></div>
                                )}
                                <div
                                  {...provided.dragHandleProps}
                                  className="cursor-grab"
                                >
                                  <GripVertical size={16} />
                                </div>
                              </div>
                            </li>
                          )}
                        </Draggable>
                      );
                    })}
                    {provided.placeholder}
                  </ul>
                )}
              </Droppable>
            </div>
          );
        })}
      </DragDropContext>
      {isModalOpen && (
            <Modal
              title="Edit Task"
              onClose={closeModal}
              task={modalTask}
              occurrenceDate={modalOccurrenceDate}
              setTasks={setTasks}
              goals={goals}
              handleSetRecurringTask={handleSetRecurringTask}
              settings={settings}
            />
          )}
       

      {/* Audio Element for Typewriter Sound */}
      <audio ref={typewriterSoundRef} src={typewriterSound} />

      {/* Editable Post-it Note */}
      <div
        className="mb-4 p-4 rounded shadow"
        style={{
          backgroundColor: '#FFFACD', // Light yellow color
          minHeight: '100px',
        }}
      >
        <textarea
          ref={textareaRef}
          value={postItNote}
          onChange={(e) => setPostItNote(e.target.value)}
          placeholder="Write your notes here..."
          className={`w-full border-0 resize-none focus:outline-none ${
            settings.darkMode
              ? 'bg-gray-800 text-white'
              : 'bg-transparent text-black'
          }`}
          style={{
            backgroundColor: 'transparent',
            overflow: 'hidden',
          }}
          rows={1}
        ></textarea>
      </div>
    </div>
  );
};

export default LogView;
