// helpers.js

// Function to get the current date as a Date object
export const getCurrentDate = () => {
  return new Date(); // Return Date object directly
};

// Function to format any given date as 'YYYY-MM-DD'
export const getDateString = (date) => {
  return date.toLocaleDateString('en-CA'); // Still used for formatting
};

