// New Function: Check if a given date is in the future
export const isDateInFuture = (date) => {
  if (!(date instanceof Date)) return false;
  const today = new Date();
  // Remove time components for accurate comparison
  today.setHours(0, 0, 0, 0);
  const compareDate = new Date(date);
  compareDate.setHours(0, 0, 0, 0);
  return compareDate > today;
};

// Function to generate recurring tasks
export const generateRecurringTasks = (task, maxOccurrences = 10) => {
  const newTasks = [];
  let recurrenceDate = new Date(task.dates[0] || getCurrentDate());
  const untilDate = task.until ? new Date(task.until) : null;
  let occurrenceCount = 0;

  while (!task.until || (untilDate && recurrenceDate <= untilDate)) {
    // Skip adding the original date (already represented by the original task)
    if (occurrenceCount > 0) {
      const newTask = {
        ...task,
        id: Date.now().toString() + Math.random(),
        dates: [getDateString(recurrenceDate)],
        originalTaskId: task.id,
      };
      newTasks.push(newTask);
    }

    // Move to the next occurrence based on recurrence type
    switch (task.recurrence) {
      case 'daily':
        recurrenceDate.setDate(recurrenceDate.getDate() + 1);
        break;
      case 'weekly':
        recurrenceDate.setDate(recurrenceDate.getDate() + 7);
        break;
      case 'monthly':
        recurrenceDate.setMonth(recurrenceDate.getMonth() + 1);
        break;
      case 'yearly':
        recurrenceDate.setFullYear(recurrenceDate.getFullYear() + 1);
        break;
      case 'custom':
        // Ensure selectedWeekdays is initialized
        const selectedWeekdays = Array.isArray(task.selectedWeekdays) ? task.selectedWeekdays : [];
        do {
          recurrenceDate.setDate(recurrenceDate.getDate() + 1);
        } while (!selectedWeekdays.includes(recurrenceDate.getDay()));
        break;
      default:
        return newTasks;
    }

    recurrenceDate.setHours(0, 0, 0, 0);
    occurrenceCount++;
    if (occurrenceCount >= maxOccurrences) break;
  }

  return newTasks;
};