// MonthView.js

import React, { useState, useEffect } from 'react';

const MonthView = ({
  tasks,
  setTasks,
  goals,
  openEditModal,
  settings,
}) => {
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDayTasks, setSelectedDayTasks] = useState([]);
  const [showTasksModal, setShowTasksModal] = useState(false);
  const [totalTasksCount, setTotalTasksCount] = useState(0);
  const [totalWorkHours, setTotalWorkHours] = useState(0);

  // Helper function to format date as 'YYYY-MM-DD' in local time
  const getDateString = (date) => date.toLocaleDateString('en-CA');

  // Function to generate the days for the current month
  const generateMonthDays = () => {
    const month = currentMonth.getMonth();
    const year = currentMonth.getFullYear();

    // Get first day of the month
    const firstDay = new Date(year, month, 1);
    const weekStartsOnSunday = settings?.weekStartsOn === 'Sun';
    const firstDayWeekday = firstDay.getDay(); // 0 (Sun) to 6 (Sat)

    // Get the number of days in the month
    const numDaysInMonth = new Date(year, month + 1, 0).getDate();

    // Create an array of all days in the month
    const monthDays = [];

    // Calculate the number of leading empty days
    const leadingEmptyDays = weekStartsOnSunday
      ? firstDayWeekday
      : (firstDayWeekday + 6) % 7;

    // Add empty days for the previous month
    for (let i = 0; i < leadingEmptyDays; i++) {
      monthDays.push(null);
    }

    // Add days of the current month
    for (let day = 1; day <= numDaysInMonth; day++) {
      monthDays.push(new Date(year, month, day));
    }

    return monthDays;
  };

  const handlePrevMonth = () => {
    setCurrentMonth(
      new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1, 1)
    );
  };

  const handleNextMonth = () => {
    setCurrentMonth(
      new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 1)
    );
  };

  const handleDayClick = (date) => {
    const dateString = getDateString(date);
    const tasksForDate = tasks.filter((task) =>
      task.dates.includes(dateString)
    );
    setSelectedDayTasks(tasksForDate);
    setShowTasksModal(true);
  };

  // Helper to check if a date is today
  const isToday = (date) => getDateString(date) === getDateString(new Date());

  // Calculate the total number of tasks for the month
  useEffect(() => {
    const month = currentMonth.getMonth();
    const year = currentMonth.getFullYear();
    const monthStart = new Date(year, month, 1);
    const monthEnd = new Date(year, month + 1, 0);

    const monthDates = [];
    for (
      let date = new Date(monthStart);
      date <= monthEnd;
      date.setDate(date.getDate() + 1)
    ) {
      monthDates.push(getDateString(new Date(date)));
    }

    let totalTasks = 0;
    tasks.forEach((task) => {
      if (task.dates.some((date) => monthDates.includes(date))) {
        totalTasks += 1;
      }
    });
    setTotalTasksCount(totalTasks);
  }, [tasks, currentMonth]);

  // Calculate total work hours for the month
  useEffect(() => {
    const month = currentMonth.getMonth();
    const year = currentMonth.getFullYear();
    const monthStart = new Date(year, month, 1);
    const monthEnd = new Date(year, month + 1, 0);

    const monthDates = [];
    for (
      let date = new Date(monthStart);
      date <= monthEnd;
      date.setDate(date.getDate() + 1)
    ) {
      monthDates.push(getDateString(new Date(date)));
    }

    let totalHours = 0;
    tasks.forEach((task) => {
      if (
        task.isShift &&
        task.dates.some((date) => monthDates.includes(date))
      ) {
        const numOccurrences = task.dates.filter((date) =>
          monthDates.includes(date)
        ).length;
        totalHours += (parseFloat(task.shiftDuration) || 0) * numOccurrences;
      }
    });
    setTotalWorkHours(totalHours);
  }, [tasks, currentMonth]);

  // Get important tasks for the current month
  const month = currentMonth.getMonth();
  const year = currentMonth.getFullYear();

  const importantTasks = tasks.filter((task) => {
    if (!task.important) return false;
    // Check if any of the task's dates are in the current month
    return task.dates.some((dateString) => {
      const date = new Date(dateString);
      return date.getMonth() === month && date.getFullYear() === year;
    });
  });

  // Generate the month days
  const monthDays = generateMonthDays();

  // Weekday headers based on settings
  const weekStartsOnSunday = settings?.weekStartsOn === 'Sun';
  const weekdays = weekStartsOnSunday
    ? ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
    : ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

  return (
    <div
      className={`p-4 min-h-screen ${
        settings.darkMode ? 'bg-gray-900 text-white' : 'bg-white text-black'
      }`}
    >
      {/* Header with Month and Navigation */}
      <div className="flex items-center justify-between mb-4">
        <button
          onClick={handlePrevMonth}
          className={`p-1 rounded-full ${
            settings.darkMode ? 'hover:bg-gray-700' : 'hover:bg-gray-200'
          }`}
        >
          &lt;
        </button>
        <h1 className="text-xl font-bold">
          {currentMonth.toLocaleDateString('en-US', {
            month: 'long',
            year: 'numeric',
          })}
        </h1>
        <button
          onClick={handleNextMonth}
          className={`p-1 rounded-full ${
            settings.darkMode ? 'hover:bg-gray-700' : 'hover:bg-gray-200'
          }`}
        >
          &gt;
        </button>
      </div>

      {/* Calendar Grid */}
      <div className="grid grid-cols-7 gap-1 flex-grow">
        {/* Weekday Headers */}
        {weekdays.map((day) => (
          <div key={day} className="text-center font-bold">
            {day}
          </div>
        ))}

        {/* Calendar Cells */}
        {monthDays.map((date, index) => {
          if (!date) return <div key={index}></div>;

          const dateString = getDateString(date);
          const tasksForDate = tasks.filter((task) =>
            task.dates.includes(dateString)
          );

          const shiftTasksForDate = tasksForDate.filter(
            (task) => task.isShift
          );

          // Get the background color from the shift task(s)
          let backgroundColor = '';
          let shiftLetter = '';

          if (shiftTasksForDate.length > 0) {
            backgroundColor =
              shiftTasksForDate[0].backgroundColor || '';
            shiftLetter = shiftTasksForDate[0].title.charAt(0);
          }

          // Check if there is any important task on that day
          const hasImportantTask = tasksForDate.some(
            (task) => task.important
          );

          // Apply special styling for today
          const isCurrentDay = isToday(date);
          const dayClassName = isCurrentDay
            ? 'bg-blue-500 text-white font-bold border h-20 md:h-28 lg:h-36 relative cursor-pointer' // Highlight today
            : 'border h-20 md:h-28 lg:h-36 relative cursor-pointer';

          return (
            <div
              key={index}
              className={dayClassName}
              style={{ backgroundColor }}
              onClick={() => handleDayClick(date)}
            >
              <div className="absolute top-1 left-1 text-xs">
                {date.getDate()}
              </div>
              {shiftLetter && (
                <div className="absolute inset-0 flex items-center justify-center">
                  <span className="text-lg font-bold">
                    {shiftLetter}
                  </span>
                </div>
              )}
              {hasImportantTask && (
                <div className="absolute bottom-1 right-1 w-2 h-2 bg-red-500 rounded-full"></div>
              )}
            </div>
          );
        })}
      </div>

      {/* Total Tasks and Total Work Hours for the Month */}
      <div className="mt-4 flex justify-between">
        <h2 className="text-lg font-bold">
          Total tasks this month: {totalTasksCount}
        </h2>
        <h2 className="text-lg font-bold">
          Total Work Hours: {totalWorkHours} hours
        </h2>
      </div>

      {/* Important Tasks Section */}
      <div className="mt-4">
        <h2 className="text-lg font-bold text-purple-600">
          Important tasks for{' '}
          {currentMonth.toLocaleDateString('en-US', {
            month: 'long',
            year: 'numeric',
          })}
        </h2>
        {importantTasks.length > 0 ? (
          <ul>
            {importantTasks.map((task) => (
              <li key={task.id} className="py-1">
                {task.dates
                  .filter((dateString) => {
                    const date = new Date(dateString);
                    return (
                      date.getMonth() === month && date.getFullYear() === year
                    );
                  })
                  .map((dateString) => (
                    <div key={dateString} className="pl-2">
                      <span className="text-purple-600">
                        {new Date(dateString).toLocaleDateString('en-US', {
                          day: 'numeric',
                          month: 'short',
                        })}
                        :
                      </span>{' '}
                      {task.title}
                    </div>
                  ))}
              </li>
            ))}
          </ul>
        ) : (
          <p>No important tasks for this month.</p>
        )}
      </div>

      {/* Tasks Modal */}
      {showTasksModal && (
        <div
          className={`fixed inset-0 flex justify-center items-center z-50 ${
            settings.darkMode
              ? 'bg-gray-900 bg-opacity-80'
              : 'bg-gray-500 bg-opacity-50'
          }`}
        >
          <div
            className={`p-4 rounded shadow-lg w-96 relative max-h-full overflow-y-auto ${
              settings.darkMode
                ? 'bg-gray-800 text-white'
                : 'bg-white text-black'
            }`}
          >
            <h2 className="text-xl font-semibold mb-4">
              Tasks for{' '}
              {selectedDayTasks[0]?.dates[0]
                ? new Date(selectedDayTasks[0].dates[0]).toLocaleDateString(
                    'en-US',
                    { day: 'numeric', month: 'long', year: 'numeric' }
                  )
                : ''}
            </h2>
            {selectedDayTasks.length > 0 ? (
              <ul>
                {selectedDayTasks.map((task) => (
                  <li
                    key={task.id}
                    className="border-b border-gray-200 py-2 flex justify-between items-center"
                  >
                    <div>
                      <span
                        className={`font-bold ${
                          task.important ? 'text-red-500' : ''
                        }`}
                      >
                        {task.title}
                      </span>
                      {task.isShift && (
                        <span className="ml-2 text-sm text-gray-600">
                          (Shift: {task.shiftDuration} hrs)
                        </span>
                      )}
                    </div>
                    <button
                      onClick={() => {
                        openEditModal(task);
                        setShowTasksModal(false);
                      }}
                      className="text-blue-500 underline"
                    >
                      Edit
                    </button>
                  </li>
                ))}
              </ul>
            ) : (
              <p>No tasks for this day.</p>
            )}
            <button
              onClick={() => setShowTasksModal(false)}
              className={`mt-4 p-2 rounded ${
                settings.darkMode
                  ? 'bg-gray-700 text-white'
                  : 'bg-gray-300 text-black'
              }`}
            >
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default MonthView;
