// HomePage.js

import React, { useRef, useState, useEffect } from 'react';
import {
  DragDropContext,
  Droppable,
  Draggable,
} from '@hello-pangea/dnd';
import {
  GripVertical,
  ChevronLeft,
  ChevronRight,
  Clock,
  Settings,
  X as CloseIcon,
} from 'lucide-react';
import successSound from '../sounds/success_sound.wav';
import typewriterSound from '../sounds/typewriter.wav';
import { LocalNotifications } from '@capacitor/local-notifications';
import { getEncouragingPhrase, getEmojiByWeek, getCurrentDate, getDateString, generateRecurringTasks, isDateInFuture } from '../utils/helpers'; // Added isDateInFuture
import Modal from './Modal'; // Adjust the import path as necessary
import LogView from './LogView';

const HomePage = ({
  
  tasks = [],
  setTasks,
  goals = [],
  setGoals,
  settings = {
    weekStartsOn: 'Mon',
    darkMode: false,
    sound: true,
    notifications: true,
    vibration: true,
    enableDailyReminders: true,
    dailyReminders: ['08:00', '20:00'],
    streakSavers: 2,
  },
  setSettings,
  streak = 0,
  setStreak,
}) => {

  const addNewTaskForDate = (date) => {
    const dateString = getDateString(date);
    const newTask = {
      id: Date.now().toString(),
      title: 'New Task',
      completed: false,
      dates: [dateString],
      time: '',
      recurrence: null,
      label: '',
      goalId: '',
      order: tasks.length, // Set order to the end of the list
    };
    setTasks((prevTasks) => [...prevTasks, newTask]);
    openEditModal(newTask);
  };
  
  const [currentDate, setCurrentDate] = useState(() => getCurrentDate());
// Helper function to check if two dates are the same day
const isSameDay = (date1, date2) => {
  return (
    date1.getDate() === date2.getDate() &&
    date1.getMonth() === date2.getMonth() &&
    date1.getFullYear() === date2.getFullYear()
  );
};

  // Helper functions
  const getDateString = (date) => date.toLocaleDateString('en-CA'); // 'YYYY-MM-DD'

  // Helper function to get the week number
  const getWeekNumber = (date) => {
    const firstDayOfYear = new Date(date.getFullYear(), 0, 1);
    const pastDaysOfYear =
      (date - firstDayOfYear + 86400000) / 86400000;
    return Math.ceil(
      (pastDaysOfYear + firstDayOfYear.getDay()) / 7
    );
  };

  const getGoalDetails = (goalId) => {
    if (!goals || !Array.isArray(goals)) return null;
    return goals.find((goal) => goal.id === goalId);
  };

  const formatTime = (time) => {
    if (!time) return '';
    const [hour, minute] = time.split(':');
    const date = new Date();
    date.setHours(hour, minute);
    return date.toLocaleTimeString([], {
      hour: 'numeric',
      minute: '2-digit',
    });
  };

  const soundRef = useRef(null); // For success sound
  const typewriterSoundRef = useRef(null); // For typewriter sound

  // State variables
  const [weeksCompleted, setWeeksCompleted] = useState(1); // Start from week 1
  const [daysMarkedAsDone, setDaysMarkedAsDone] = useState([]);
  const [encouragingPhrase, setEncouragingPhrase] = useState(
    getEncouragingPhrase()
  );
  const [currentEmoji, setCurrentEmoji] = useState(
    getEmojiByWeek(weeksCompleted)
  );
  const [animateStreak, setAnimateStreak] = useState(false);
  const [currentWeekOffset, setCurrentWeekOffset] = useState(0); // For week navigation
  const [showStreakSaverPopup, setShowStreakSaverPopup] = useState(false);
  const [streakSaversUsed, setStreakSaversUsed] = useState([]); // Ensure initialized as array
  const [isSettingsOpen, setIsSettingsOpen] = useState(false); // State for settings modal

  // State for modal
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [currentTask, setCurrentTask] = useState(null);

  const prevStreakRef = useRef(streak);
  const prevWeekNumberRef = useRef(getWeekNumber(new Date()));

  // Initialize streak savers from settings or start with 2
  const [streakSavers, setStreakSavers] = useState(
    settings.streakSavers !== undefined ? settings.streakSavers : 2
  );

  // New State Variables for Testing Mode
  const [testingMode, setTestingMode] = useState(false);
  const [testCurrentDate, setTestCurrentDate] = useState(null);

  // State variable for selected date
  const [selectedDate, setSelectedDate] = useState(getCurrentDate());

  // State variable for "Mark Day as Done" confirmation
  const [showMarkDoneConfirm, setShowMarkDoneConfirm] = useState(false);



  // Helper function to determine if a task occurs on a specific date
  const doesTaskOccurOnDate = (task, date) => {
    const dateString = getDateString(date);

    // Check if the date is in the exceptions array
    if ((task.exceptions || []).includes(dateString)) {
      return false;
    }

    // Check if the date is in the task's dates array
    if ((task.dates || []).includes(dateString)) {
      return true;
    }

    // Handle recurring tasks
    if (task.recurrence) {
      const taskStartDate = new Date(task.dates[0]);
      taskStartDate.setHours(0, 0, 0, 0); // Ensure time is set to midnight
      const taskEndDate = task.until ? new Date(task.until) : null;

      // If task.until is set, and date is after until date, return false
      if (taskEndDate && date > taskEndDate) {
        return false;
      }

      // If date is before task start date, return false
      if (date < taskStartDate) {
        return false;
      }

      switch (task.recurrence) {
        case 'daily':
          return true; // Occurs every day
        case 'weekly':
          // Occurs on the same weekday as the task's start date
          return date.getDay() === taskStartDate.getDay();
        case 'monthly':
          if (task.repeatOnLastDayOfMonth) {
            // Check if the date is the last day of the month
            const nextDay = new Date(date);
            nextDay.setDate(date.getDate() + 1);
            return nextDay.getDate() === 1;
          } else {
            // Occurs on the same day of the month as the task's start date
            return date.getDate() === taskStartDate.getDate();
          }
        case 'yearly':
          // Occurs on the same month and day as the task's start date
          return (
            date.getDate() === taskStartDate.getDate() &&
            date.getMonth() === taskStartDate.getMonth()
          );
        case 'custom':
          if (task.selectedWeekdays) {
            // Occurs on the selected weekdays
            return (task.selectedWeekdays || []).includes(date.getDay());
          }
          return false;
        default:
          return false;
      }
    }

    return false;
  };

  // Use 🌞 as the streak saver icon
  const streakSaverIcon = '🌞';

  // Store scheduled reminder notification IDs
  const [reminderNotificationIds, setReminderNotificationIds] = useState([]);

  useEffect(() => {
    setCurrentDate(getCurrentDate());

    setEncouragingPhrase(getEncouragingPhrase());
  }, [weeksCompleted]);

  useEffect(() => {
    if (streak !== prevStreakRef.current) {
      // Trigger streak animation
      setAnimateStreak(true);
      setTimeout(() => setAnimateStreak(false), 1000); // Duration of animation
      prevStreakRef.current = streak;
    }
  }, [streak]);

  // Ensure that goals is always an array
  useEffect(() => {
    if (!goals || !Array.isArray(goals)) {
      console.warn('goals is not an array, resetting to empty array');
      setGoals([]);
    }
  }, [goals, setGoals]);

  // Effect to check for week change
  useEffect(() => {
    const checkWeekChange = () => {
      const currentDate = getCurrentDate(); // Use helper function
      const currentWeekNumber = getWeekNumber(currentDate);
      if (currentWeekNumber !== prevWeekNumberRef.current) {
        // Week has changed
        // Check if all goals were achieved and there are goals for the week
        const allGoalsAchieved =
          goals && goals.length > 0
            ? goals.every((goal) => goal.progress >= goal.target)
            : false;

        if (allGoalsAchieved) {
          setWeeksCompleted(
            (prevWeeksCompleted) => prevWeeksCompleted + 1
          );
          setCurrentEmoji(
            getEmojiByWeek(weeksCompleted + 1)
          );

          // Award a streak saver
          setStreakSavers((prevStreakSavers) => {
            const newStreakSavers = prevStreakSavers + 1;
            setSettings((prevSettings) => ({
              ...prevSettings,
              streakSavers: newStreakSavers,
            }));
            return newStreakSavers;
          });
          setShowStreakSaverPopup(true);
        }

        // Reset goals progress for the new week
        setGoals((prevGoals) =>
          prevGoals.map((goal) => ({ ...goal, progress: 0 }))
        );

        // Reset other state for the new week
        setDaysMarkedAsDone([]);
        prevWeekNumberRef.current = currentWeekNumber;
      }
    };

    checkWeekChange(); // Run on component mount

    const interval = setInterval(checkWeekChange, 60 * 1000); // Check every minute

    return () => clearInterval(interval); // Cleanup on unmount
  }, [goals, weeksCompleted, setSettings, setGoals, getCurrentDate]);

  // Effect to use streak saver if previous day was not marked as done
  useEffect(() => {
    const today = getCurrentDate();
    const yesterday = new Date(today);
    yesterday.setDate(today.getDate() - 1);
    const yesterdayString = getDateString(yesterday);

    if (
      streak > 0 &&
      !( (daysMarkedAsDone || []).includes(yesterdayString) ) &&
      streakSavers > 0 &&
      !isDateInFuture(yesterday) &&
      !( (streakSaversUsed || []).includes(yesterdayString) )
    ) {
      // Use a streak saver
      setDaysMarkedAsDone((prevDays) => [
        ...prevDays,
        yesterdayString,
      ]);
      setStreakSavers((prevStreakSavers) => {
        const newStreakSavers = prevStreakSavers - 1;
        setSettings((prevSettings) => ({
          ...prevSettings,
          streakSavers: newStreakSavers,
        }));
        return newStreakSavers;
      });
      setStreakSaversUsed((prevUsed) => [
        ...prevUsed,
        yesterdayString,
      ]);
    }
  }, [
    daysMarkedAsDone,
    streakSavers,
    setSettings,
    streakSaversUsed,
    getCurrentDate,
    streak,
  ]);

  useEffect(() => {
    scheduleDailyReminders();
    return () => cancelDailyReminders();
  }, [
    settings.enableMorningReminder,
    settings.morningReminderTime,
    settings.enableAfternoonReminder,
    settings.afternoonReminderTime,
    settings.enableEveningReminder,
    settings.eveningReminderTime,
  ]);

  // Function to schedule daily reminders
  const scheduleDailyReminders = async () => {
    // Cancel existing reminders
    await cancelDailyReminders();

    const ids = [];
    const now = new Date();

    // Morning Reminder
    if (settings.enableMorningReminder && settings.morningReminderTime) {
      const [hour, minute] = settings.morningReminderTime.split(':').map(Number);
      let reminderDate = new Date();
      reminderDate.setHours(hour, minute, 0, 0);
      if (reminderDate < now) {
        reminderDate.setDate(reminderDate.getDate() + 1);
      }
      const notificationId = Math.floor(Math.random() * 100000);
      ids.push(notificationId);
      await LocalNotifications.schedule({
        notifications: [
          {
            title: 'Morning Reminder',
            body: 'Good morning! Check your tasks for today.',
            id: notificationId,
            schedule: { at: reminderDate, repeats: true, every: 'day' },
            sound: settings.sound ? 'default' : null,
          },
        ],
      });
    }

    // Afternoon Reminder
    if (settings.enableAfternoonReminder && settings.afternoonReminderTime) {
      const [hour, minute] = settings.afternoonReminderTime.split(':').map(Number);
      let reminderDate = new Date();
      reminderDate.setHours(hour, minute, 0, 0);
      if (reminderDate < now) {
        reminderDate.setDate(reminderDate.getDate() + 1);
      }
      const notificationId = Math.floor(Math.random() * 100000);
      ids.push(notificationId);
      await LocalNotifications.schedule({
        notifications: [
          {
            title: 'Afternoon Reminder',
            body: 'Good afternoon! Keep up with your tasks.',
            id: notificationId,
            schedule: { at: reminderDate, repeats: true, every: 'day' },
            sound: settings.sound ? 'default' : null,
          },
        ],
      });
    }

    // Evening Reminder
    if (settings.enableEveningReminder && settings.eveningReminderTime) {
      const [hour, minute] = settings.eveningReminderTime.split(':').map(Number);
      let reminderDate = new Date();
      reminderDate.setHours(hour, minute, 0, 0);
      if (reminderDate < now) {
        reminderDate.setDate(reminderDate.getDate() + 1);
      }
      const notificationId = Math.floor(Math.random() * 100000);
      ids.push(notificationId);
      await LocalNotifications.schedule({
        notifications: [
          {
            title: 'Evening Reminder',
            body: 'Good evening! Wrap up your tasks for today.',
            id: notificationId,
            schedule: { at: reminderDate, repeats: true, every: 'day' },
            sound: settings.sound ? 'default' : null,
          },
        ],
      });
    }

    setReminderNotificationIds(ids);
  };

  // Function to cancel daily reminders
  const cancelDailyReminders = async () => {
    if (reminderNotificationIds.length > 0) {
      await LocalNotifications.cancel({
        notifications: reminderNotificationIds.map((id) => ({ id })),
      });
      setReminderNotificationIds([]);
    }
  };

  // Function to schedule task notifications
  const scheduleNotification = async (task) => {
    if (!settings.notifications || !task.reminders) return;

    for (let i = 0; i < (task.reminders || []).length; i++) {
      let reminderDateTime;
      const reminder = task.reminders[i];

      if (reminder.type === 'custom') {
        reminderDateTime = new Date(reminder.datetime);
      } else {
        if (!task.time) continue; // Skip if no time is set
        const taskDateTime = new Date(`${task.dates[0]}T${task.time}`);
        reminderDateTime = new Date(taskDateTime);
        switch (reminder.type) {
          case 'atEventTime':
            // reminderDateTime is the same as taskDateTime
            break;
          case '10minBefore':
            reminderDateTime.setMinutes(reminderDateTime.getMinutes() - 10);
            break;
          case '30minBefore':
            reminderDateTime.setMinutes(reminderDateTime.getMinutes() - 30);
            break;
          case '1hrBefore':
            reminderDateTime.setHours(reminderDateTime.getHours() - 1);
            break;
          case '1dayBefore':
            reminderDateTime.setDate(reminderDateTime.getDate() - 1);
            break;
          case '2daysBefore':
            reminderDateTime.setDate(reminderDateTime.getDate() - 2);
            break;
          default:
            break;
        }
      }

      if (reminderDateTime > new Date()) {
        const notificationId = parseInt(
          task.id.toString().replace('.', '') + i.toString()
        );
        await LocalNotifications.schedule({
          notifications: [
            {
              title: 'Task Reminder',
              body: task.title,
              id: notificationId,
              schedule: { at: reminderDateTime },
              sound: settings.sound ? 'default' : null,
            },
          ],
        });
      }
    }
  };

  // Function to cancel scheduled task notifications
  const cancelNotification = async (task) => {
    if (task.reminders && task.reminders.length > 0) {
      for (let i = 0; i < (task.reminders || []).length; i++) {
        const notificationId = parseInt(
          task.id.toString().replace('.', '') + i.toString()
        );
        await LocalNotifications.cancel({
          notifications: [{ id: notificationId }],
        });
      }
    }
  };

  const toggleTaskCompletion = (taskId, taskDate) => {
    if (isTodayMarkedAsDone) {
      // Prevent toggling tasks if the day is marked as done
      return;
    }
  
    setTasks((prevTasks) => {
      const updatedTasks = prevTasks.map((task) => {
        if (task.id === taskId) {
          const updatedTask = {
            ...task,
            completedDates: task.completedDates || [], // Ensure completedDates array exists
          };

          const taskDateString = getDateString(taskDate); // Format the taskDate

          // Check if the task was already completed for this specific date
          if (updatedTask.completedDates.includes(taskDateString)) {
            // If already completed, remove this date from completedDates (uncheck it)
            updatedTask.completedDates = updatedTask.completedDates.filter(
              (date) => date !== taskDateString
            );
          } else {
            // If not completed, add this date to completedDates (mark it as completed)
            updatedTask.completedDates.push(taskDateString);
          }

          // Cancel or schedule notifications based on the task's completion
          if (updatedTask.completedDates.includes(taskDateString)) {
            cancelNotification(updatedTask);
            playTypewriterSound();
          } else if (updatedTask.reminders && updatedTask.reminders.length > 0) {
            scheduleNotification(updatedTask);
          }

          return updatedTask;
        }
        return task;
      });

      // Update goal progress if applicable
      if (goals && goals.length > 0) {
        const completedTask = updatedTasks.find((task) => task.id === taskId);

        if (completedTask && completedTask.goalId) {
          const relatedGoal = goals.find((goal) => goal.id === completedTask.goalId);

          if (relatedGoal) {
            const newProgress = updatedTasks.filter(
              (t) => t.goalId === completedTask.goalId && (t.completedDates || []).includes(getDateString(taskDate))
            ).length;

            setGoals((prevGoals) =>
              prevGoals.map((g) =>
                g.id === relatedGoal.id ? { ...g, progress: newProgress } : g
              )
            );
          }
        }
      }

      return updatedTasks;
    });
  };
  

  const playSound = () => {
    if (settings.sound && soundRef.current) {
      soundRef.current.currentTime = 0; // Reset playback to the beginning
      soundRef.current.play().catch((error) => {
        console.warn("Playback failed for soundRef: ", error);
      });
    }
  };

  const playTypewriterSound = () => {
    if (settings.sound && typewriterSoundRef.current) {
      typewriterSoundRef.current.currentTime = 0;
      typewriterSoundRef.current.play().catch((error) => {
        console.warn("Playback failed for typewriterSoundRef: ", error);
      });
    }
  };

  const onDragEnd = (result) => {
    const { destination, source, draggableId } = result;

    if (!destination) return;

    if (
      destination.droppableId === source.droppableId &&
      destination.index === source.index
    )
      return;

    const [taskId, sourceDate] = draggableId.split('::');
    const destDate = destination.droppableId;

    setTasks((prevTasks) => {
      const tasksCopy = prevTasks.map((task) => ({
        ...task,
        dates: [...(task.dates || [])],
        exceptions: [...(task.exceptions || [])],
      }));

      const taskIndex = tasksCopy.findIndex((task) => task.id === taskId);

      if (taskIndex === -1) return prevTasks;

      const movedTask = tasksCopy[taskIndex];

      // Moving task between dates
      if (sourceDate !== destDate) {
        if (movedTask.recurrence) {
          // Ensure exceptions array is initialized
          movedTask.exceptions = movedTask.exceptions || [];

          // For recurring tasks, add sourceDate to exceptions
          if (!movedTask.exceptions.includes(sourceDate)) {
            movedTask.exceptions.push(sourceDate);
          }

          // Ensure dates array is initialized
          movedTask.dates = movedTask.dates || [];

          // Add destDate to dates
          if (!movedTask.dates.includes(destDate)) {
            movedTask.dates.push(destDate);
          }
        } else {
          // Ensure dates array is initialized
          movedTask.dates = movedTask.dates || [];

          // For non-recurring tasks, update dates array
          // Remove from sourceDate
          movedTask.dates = movedTask.dates.filter((date) => date !== sourceDate);

          // Add to destDate
          if (!movedTask.dates.includes(destDate)) {
            movedTask.dates.push(destDate);
          }
        }
      }

      // Update order in destination date
      const tasksInDestDate = tasksCopy
        .filter((task) => doesTaskOccurOnDate(task, new Date(destDate)))
        .sort(
          (a, b) => (a.order || 0) - (b.order || 0) || a.id.localeCompare(b.id)
        );

      // Remove the moved task from its original position
      const movedTaskIndex = tasksInDestDate.findIndex((task) => task.id === taskId);
      if (movedTaskIndex !== -1) {
        tasksInDestDate.splice(movedTaskIndex, 1);
      }

      // Insert the moved task into the destination array at the new index
      tasksInDestDate.splice(destination.index, 0, movedTask);

      // Update the order property for tasks in the destination date
      tasksInDestDate.forEach((task, index) => {
        task.order = index;
      });

      return tasksCopy;
    });
  };

  const handleMarkDayAsDone = () => {
    const today = getDateString(selectedDate);
    if (!((daysMarkedAsDone || []).includes(today))) { // Safeguarded
        setDaysMarkedAsDone((prevDays) => [...prevDays, today]);
        playSound();

        // Update streak
        setStreak((prevStreak) => prevStreak + 1);

        // Reset encouraging phrase
        setEncouragingPhrase(getEncouragingPhrase());
    }
  };

  // Week Navigation Functions
  const handlePreviousWeek = () => {
    setCurrentWeekOffset((prev) => prev - 1);
  };

  const handleNextWeek = () => {
    setCurrentWeekOffset((prev) => prev + 1);
  };

  const getWeekDates = () => {
    const current = getCurrentDate(); // Use helper function
    const adjustedDate = new Date(current);
    adjustedDate.setDate(current.getDate() + currentWeekOffset * 7);
    const week = [];
    const weekStartsOn = settings && settings.weekStartsOn === 'Sun' ? 0 : 1; // 0 for Sunday, 1 for Monday
    const day = adjustedDate.getDay();
    const diff =
      (day < weekStartsOn ? 7 : 0) + day - weekStartsOn;
    const firstDayOfWeek = new Date(adjustedDate);
    firstDayOfWeek.setDate(adjustedDate.getDate() - diff);
    firstDayOfWeek.setHours(0, 0, 0, 0); // Set time to midnight
    for (let i = 0; i < 7; i++) {
      const date = new Date(firstDayOfWeek);
      date.setDate(firstDayOfWeek.getDate() + i);
      week.push(date);
    }
    return week;
  };

  const weekDates = getWeekDates();

  const selectedDateString = getDateString(selectedDate);

  // Filter tasks for the selected date
  let todayTasks = tasks
    .filter((task) => doesTaskOccurOnDate(task, selectedDate))
    .sort(
      (a, b) => (a.order || 0) - (b.order || 0) || a.id.localeCompare(b.id)
    );

  // Remove shift tasks from today's tasks
  todayTasks = todayTasks.filter((task) => !task.isShift);

  const allTasksCompleted =
    todayTasks.length > 0 &&
    todayTasks.every((task) => (task.completedDates || []).includes(selectedDateString));

  const isTodayMarkedAsDone = (daysMarkedAsDone || []).includes(selectedDateString); // Safeguarded

  // Function to handle setting recurring tasks
  const handleSetRecurringTask = async (task) => {
    // Generate recurring tasks
    const recurringTasks = generateRecurringTasks(task);

    // Combine the original task with the recurring tasks
    const allTasks = [task, ...recurringTasks];

    // Collect previous tasks that match the task id or originalTaskId
    const tasksToCancel = tasks.filter(
      (t) => t.id === task.id || t.originalTaskId === task.id
    );

    // Update the tasks state
    setTasks((prevTasks) => {
      // Remove any previous occurrences of this task
      const newTasks = prevTasks.filter(
        (t) => t.id !== task.id && t.originalTaskId !== task.id
      );

      return [...newTasks, ...allTasks];
    });

    // Cancel notifications for previous occurrences of this task
    for (const t of tasksToCancel) {
      await cancelNotification(t);
    }

    // Schedule notifications for the new tasks
    for (const taskItem of allTasks) {
      await scheduleNotification(taskItem);
    }
  };

  // Function to open the edit modal
  const openEditModal = (task) => {
    setCurrentTask(task);
    setIsModalOpen(true);
  };

  // Function to close the edit modal
  const closeModal = () => {
    setIsModalOpen(false);
    setCurrentTask(null);
  };

  return (
    <div
      className={`p-4 ${
        settings.darkMode
          ? 'bg-gray-900 text-gray-100'
          : 'bg-gray-100 text-black'
      } relative`}
    >
      {/* Settings Button */}
      <button
        onClick={() => setIsSettingsOpen(true)}
        className={`absolute top-4 right-4 ${
          settings.darkMode
            ? 'text-gray-300 hover:text-white'
            : 'text-gray-600 hover:text-gray-800'
        }`}
        title="Settings"
      >
        <Settings size={24} />
      </button>

      {/* Rest of your component */}
      <h1 className="text-2xl font-bold mb-2">Weekly Bloom </h1>

      {/* Streak Overview Section */}
      <div className="flex flex-col items-center mb-2">
        <div className="relative">
          <div
            className={`w-32 h-32 rounded-full flex items-center justify-center ${
              animateStreak ? 'animate-streak' : ''
            } ${
              settings.darkMode ? 'bg-gray-800' : 'bg-green-200'
            }`}
          >
            <span className="text-4xl font-bold">{streak}</span>
          </div>
          <span className="text-6xl absolute top-0 right-0 transform translate-x-1/4 -translate-y-1/4">
            {currentEmoji}
          </span>
        </div>
        <p
          className={`mt-2 text-center text-sm ${
            settings.darkMode ? 'text-gray-300' : 'text-gray-600'
          }`}
        >
          {encouragingPhrase}
        </p>
      </div>

      {/* Month Navigation Arrows */}
<div className="flex items-center justify-between mb-2">
  <button onClick={handlePreviousWeek}>
    <ChevronLeft size={24} />
  </button>
  <h2 className="text-lg font-semibold">
    {weekDates[0].toLocaleDateString('en-US', {
      month: 'long',
      year: 'numeric',
    })}
  </h2>
  <button onClick={handleNextWeek}>
    <ChevronRight size={24} />
  </button>
</div>


      {/* Week Day Selector */}
      <div className="flex justify-between mb-2">
      {weekDates && weekDates.length > 0 ? (
  weekDates.map((date, index) => {
    const dateString = getDateString(date);
    const isToday = dateString === getDateString(getCurrentDate());
    const isSelected = dateString === getDateString(selectedDate);
    const isDayMarkedAsDone = (daysMarkedAsDone || []).includes(dateString);
    const isDaySavedByStreakSaver = (streakSaversUsed || []).includes(dateString);

    // Get tasks for the date
    const tasksForDate = tasks.filter((task) => doesTaskOccurOnDate(task, date));

    // Extract shift tasks
    const shiftTasks = tasksForDate.filter((task) => task.isShift);
    const nonShiftTasks = tasksForDate.filter((task) => !task.isShift);

    const hasImportantTask = nonShiftTasks.some((task) => task.important);

    const tasksWithBackground = nonShiftTasks.filter(
      (task) => task.backgroundColor
    );

    // Change color based on the day
    const dayColorClass = (() => {
      if (isDaySavedByStreakSaver) return 'bg-yellow-500';
      if (isDayMarkedAsDone) return 'bg-green-500';
      if (isToday) return 'bg-blue-500';
      return settings.darkMode ? 'bg-gray-700' : 'bg-gray-200';
    })();

    return (
      <div
        key={index}
        className={`flex flex-col items-center relative cursor-pointer ${
          isSelected ? 'border border-dotted border-blue-900 rounded-full' : ''
        }`}
        onClick={() => setSelectedDate(date)}
      >
        {/* Background colored tasks */}
        {tasksWithBackground.map((task, idx) => (
          <div
            key={idx}
            className="absolute top-0 left-0 w-full h-full rounded-full"
            style={{
              backgroundColor: task.backgroundColor,
              opacity: 0.3,
            }}
          ></div>
        ))}

        <span className="text-xs mb-1 relative z-10">
          {date.toLocaleDateString('en-US', { weekday: 'short' })}
        </span>
        <div
          className={`w-10 h-10 rounded-full relative ${dayColorClass} flex items-center justify-center`}
        >
          <span className="text-sm relative z-10">{date.getDate()}</span>
          {hasImportantTask && (
            <div className="w-2 h-2 bg-red-500 rounded-full absolute bottom-0"></div>
          )}
          {isDaySavedByStreakSaver && (
            <span className="absolute bottom-0 text-sm">
              {streakSaverIcon}
            </span>
          )}
        </div>
        {/* Display shift name and color next to the day */}
        {shiftTasks.map((shiftTask) => (
          <div
            key={shiftTask.id}
            className="mt-1 px-2 py-1 rounded text-xs text-center"
            style={{
              backgroundColor: shiftTask.backgroundColor || '#ccc',
              color: '#000',
            }}
          >
            {shiftTask.title[0]}
          </div>
        ))}
      </div>
    );
  })
) : (
  <div>No dates available</div>
)}
</div>

      {/* Display Selected Date with "+" button */}
<div className="flex items-center justify-between mb-2">
  <h2 className="text-lg font-semibold">
    {isSameDay(selectedDate, getCurrentDate()) ? 'Today is: ' : ''}
    {selectedDate.toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'long',
      day: 'numeric',
    })}
  </h2>
  <button
    onClick={() => addNewTaskForDate(selectedDate)}
    className="p-2 bg-blue-500 text-white rounded-full"
  >
    +
  </button>
</div>


      {/* Task List */}
      <DragDropContext onDragEnd={onDragEnd}>
        <Droppable droppableId={selectedDateString}>
          {(provided) => (
            <ul
              {...provided.droppableProps}
              ref={provided.innerRef}
              className={`min-h-[50px] p-1 rounded-lg shadow mb-2 ${
                settings.darkMode ? 'bg-gray-800' : 'bg-white'
              }`}
            >
              {todayTasks.map((task, idx) => {
                const goalDetails = getGoalDetails(task.goalId);
                return (
                  <Draggable
                    key={`${task.id}::${selectedDateString}`}
                    draggableId={`${task.id}::${selectedDateString}`}
                    index={idx}
                  >
                    {(provided) => (
                      <li
                        ref={provided.innerRef}
                        {...provided.draggableProps}
                        {...provided.dragHandleProps}
                        className={`flex justify-between items-center p-1 mb-1 shadow-sm rounded-lg ${
                          Array.isArray(task.completedDates) && task.completedDates.includes(selectedDateString)
                            ? 'line-through text-gray-500 opacity-50'
                            : ''
                        } ${
                          settings.darkMode
                            ? 'bg-gray-900 text-gray-100'
                            : 'bg-white text-black'
                        }`}
                        onDoubleClick={() => openEditModal(task)}
                      >
                        <div className="flex items-center">
                          <input
                            type="checkbox"
                            checked={Array.isArray(task.completedDates) && task.completedDates.includes(selectedDateString)}
                            onChange={() => toggleTaskCompletion(task.id, selectedDate)}
                            className="mr-2"
                            disabled={isTodayMarkedAsDone}
                          />
    
                          <span className="text-sm">
                            {task.time && (
                              <span className="mr-1">
                                {formatTime(task.time)}
                              </span>
                            )}
                            {task.title}
                            {goalDetails && (
                              <span className="ml-1 text-xs text-gray-500">
                                ({goalDetails.title})
                              </span>
                            )}
                            {task.important && (
                              <span className="ml-1 text-red-500 font-bold">
                                *
                              </span>
                            )}
                          </span>
                        </div>

                        <div className="flex items-center">
                          {/* Clock icon if any reminders are set */}
                          {Array.isArray(task.reminders) && task.reminders.length > 0 && (
                            <Clock
                              size={16}
                              className="inline mr-1"
                            />
                          )}
                          {goalDetails && (
                            <div
                              className="w-2 h-2 rounded-full mr-1"
                              style={{
                                backgroundColor: goalDetails.color,
                              }}
                            ></div>
                          )}
                          <div className="cursor-grab">
                            <GripVertical size={16} />
                          </div>
                        </div>
                      </li>
                    )}
                  </Draggable>
                );
              })}
              {provided.placeholder}
            </ul>
          )}
        </Droppable>
      </DragDropContext>

      {/* Mark Day as Done Button */}
      {allTasksCompleted && (
        <button
          onClick={
            !isTodayMarkedAsDone ? () => setShowMarkDoneConfirm(true) : undefined
          }
          className={`${
            isTodayMarkedAsDone ? 'bg-green-500' : 'bg-blue-500'
          } text-white px-4 py-2 rounded mt-4 w-full`}
        >
          {isTodayMarkedAsDone ? 'Day completed!' : 'Mark day as done'}
        </button>
      )}

      {/* Confirmation Popup for Marking Day as Done */}
      {showMarkDoneConfirm && (
        <div
          className={`fixed inset-0 flex items-center justify-center ${
            settings.darkMode
              ? 'bg-gray-900 bg-opacity-80'
              : 'bg-black bg-opacity-50'
          }`}
        >
          <div
            className={`rounded-lg shadow-lg p-4 ${
              settings.darkMode
                ? 'bg-gray-800 text-white'
                : 'bg-white text-black'
            }`}
          >
            <p className="text-center mb-4 text-lg">
              Mark this day as done?
            </p>
            <div className="flex justify-around">
              <button
                onClick={() => {
                  handleMarkDayAsDone();
                  setShowMarkDoneConfirm(false);
                }}
                className="bg-green-500 text-white px-4 py-2 rounded"
              >
                Yes
              </button>
              <button
                onClick={() => setShowMarkDoneConfirm(false)}
                className="bg-red-500 text-white px-4 py-2 rounded"
              >
                No
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Streak Saver Popup */}
      {showStreakSaverPopup && (
        <div
          className={`fixed inset-0 flex items-center justify-center ${
            settings.darkMode
              ? 'bg-gray-900 bg-opacity-80'
              : 'bg-black bg-opacity-50'
          }`}
        >
          <div
            className={`rounded-lg shadow-lg p-4 ${
              settings.darkMode
                ? 'bg-gray-800 text-white'
                : 'bg-white text-black'
            }`}
          >
            <p className="text-center mb-4 text-lg">
              {streakSaverIcon} You got a Streak Saver to help you save
              your streak!
            </p>
            <button
              onClick={() => setShowStreakSaverPopup(false)}
              className="bg-blue-500 text-white px-4 py-2 rounded w-full"
            >
              OK
            </button>
          </div>
        </div>
      )}

      {/* Settings Modal */}
      {isSettingsOpen && (
        <div
          className={`fixed inset-0 ${
            settings.darkMode
              ? 'bg-gray-900 bg-opacity-80'
              : 'bg-gray-500 bg-opacity-50'
          } flex justify-center items-center z-50`}
        >
          <div
            className={`rounded-lg shadow-lg p-6 w-96 relative ${
              settings.darkMode
                ? 'bg-gray-800 text-white'
                : 'bg-white text-black'
            }`}
          >
            {/* Close Button */}
            <button
              onClick={() => setIsSettingsOpen(false)}
              className="absolute top-2 right-2 text-gray-600 hover:text-gray-800"
              title="Close"
            >
              <CloseIcon size={20} />
            </button>
            {/* Settings Content */}
            <h1 className="text-2xl font-bold mb-4">Settings</h1>
            {/* Settings Form */}
            <div className="mb-4">
              <label className="block mb-2">Week Starts On:</label>
              <select
                value={settings.weekStartsOn}
                onChange={(e) =>
                  setSettings({
                    ...settings,
                    weekStartsOn: e.target.value,
                  })
                }
                className={`w-full p-2 border rounded ${
                  settings.darkMode
                    ? 'bg-gray-700 text-white'
                    : 'bg-white text-black'
                }`}
              >
                <option value="Mon">Monday</option>
                <option value="Sun">Sunday</option>
              </select>
            </div>
            {/* Testing Mode Toggle */}
            <div className="mb-4">
              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={testingMode}
                  onChange={(e) => setTestingMode(e.target.checked)}
                  className="mr-2"
                />
                Enable Testing Mode
              </label>
            </div>
            {/* Date Picker for Testing Mode */}
            {testingMode && (
              <div className="mb-4">
                <label className="block mb-2">Set Current Date:</label>
                <input
                  type="date"
                  value={
                    testCurrentDate
                      ? getDateString(new Date(testCurrentDate))
                      : ''
                  }
                  onChange={(e) => setTestCurrentDate(e.target.value)}
                  className={`w-full p-2 border rounded ${
                    settings.darkMode
                      ? 'bg-gray-700 text-white'
                      : 'bg-white text-black'
                  }`}
                />
              </div>
            )}
            {/* Morning Reminder */}
            <div className="mb-4">
              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={settings.enableMorningReminder}
                  onChange={(e) =>
                    setSettings({
                      ...settings,
                      enableMorningReminder: e.target.checked,
                    })
                  }
                  className="mr-2"
                />
                Enable Morning Reminder
              </label>
              {settings.enableMorningReminder && (
                <div className="mt-2">
                  <label className="block mb-1">Time:</label>
                  <input
                    type="time"
                    value={settings.morningReminderTime}
                    onChange={(e) =>
                      setSettings({
                        ...settings,
                        morningReminderTime: e.target.value,
                      })
                    }
                    className={`w-full p-2 border rounded ${
                      settings.darkMode
                        ? 'bg-gray-700 text-white'
                        : 'bg-white text-black'
                    }`}
                  />
                </div>
              )}
            </div>

            {/* Afternoon Reminder */}
            <div className="mb-4">
              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={settings.enableAfternoonReminder}
                  onChange={(e) =>
                    setSettings({
                      ...settings,
                      enableAfternoonReminder: e.target.checked,
                    })
                  }
                  className="mr-2"
                />
                Enable Afternoon Reminder
              </label>
              {settings.enableAfternoonReminder && (
                <div className="mt-2">
                  <label className="block mb-1">Time:</label>
                  <input
                    type="time"
                    value={settings.afternoonReminderTime}
                    onChange={(e) =>
                      setSettings({
                        ...settings,
                        afternoonReminderTime: e.target.value,
                      })
                    }
                    className={`w-full p-2 border rounded ${
                      settings.darkMode
                        ? 'bg-gray-700 text-white'
                        : 'bg-white text-black'
                    }`}
                  />
                </div>
              )}
            </div>

            {/* Evening Reminder */}
            <div className="mb-4">
              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={settings.enableEveningReminder}
                  onChange={(e) =>
                    setSettings({
                      ...settings,
                      enableEveningReminder: e.target.checked,
                    })
                  }
                  className="mr-2"
                />
                Enable Evening Reminder
              </label>
              {settings.enableEveningReminder && (
                <div className="mt-2">
                  <label className="block mb-1">Time:</label>
                  <input
                    type="time"
                    value={settings.eveningReminderTime}
                    onChange={(e) =>
                      setSettings({
                        ...settings,
                        eveningReminderTime: e.target.value,
                      })
                    }
                    className={`w-full p-2 border rounded ${
                      settings.darkMode
                        ? 'bg-gray-700 text-white'
                        : 'bg-white text-black'
                    }`}
                  />
                </div>
              )}
            </div>

            <div className="mb-4">
              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={settings.notifications}
                  onChange={(e) =>
                    setSettings({
                      ...settings,
                      notifications: e.target.checked,
                    })
                  }
                  className="mr-2"
                />
                Enable Notifications
              </label>
            </div>
            <div className="mb-4">
              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={settings.sound}
                  onChange={(e) =>
                    setSettings({
                      ...settings,
                      sound: e.target.checked,
                    })
                  }
                  className="mr-2"
                />
                Enable Sound
              </label>
            </div>
            <div className="mb-4">
              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={settings.vibration}
                  onChange={(e) =>
                    setSettings({
                      ...settings,
                      vibration: e.target.checked,
                    })
                  }
                  className="mr-2"
                />
                Enable Vibration
              </label>
            </div>
            <div className="mb-4">
              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={settings.darkMode}
                  onChange={(e) =>
                    setSettings({
                      ...settings,
                      darkMode: e.target.checked,
                    })
                  }
                  className="mr-2"
                />
                Enable Dark Mode
              </label>
            </div>
          </div>
        </div>
      )}

      {/* Render the Modal */}
      {isModalOpen && currentTask && (
        <Modal
          title="Edit Task"
          onClose={closeModal}
          task={currentTask}
          setTasks={setTasks}
          goals={goals}
          handleSetRecurringTask={(editedTask) => {
            setTasks((prevTasks) =>
              prevTasks.map((task) => (task.id === editedTask.id ? editedTask : task))
            );
          }}
          settings={settings}
        />
      )}

      <audio ref={soundRef} src={successSound} />
      <audio ref={typewriterSoundRef} src={typewriterSound} />

      
    </div>
  );
};

export default HomePage;